SELECT CASE WHEN s.city IN ('Bangkok', 'Tokyo') THEN 'priority' ELSE 'other' END AS city_group, ROUND(AVG(oi.quantity), 2) AS avg_quantity FROM order_items oi INNER JOIN products p ON oi.product_id = p.id INNER JOIN suppliers s ON p.supplier_id = s.id WHERE s.country = 'UK' GROUP BY CASE WHEN s.city IN ('Bangkok', 'Tokyo') THEN 'priority' ELSE 'other' END HAVING avg_quantity > 45;
